(()=>{'use strict';
const KEY='cirurgia-library-v2',RECOVERY='cirurgia-notes-recovery-v1',esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),fold=s=>String(s).normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
let root,selected=null,query='',category='',filter='all',data=[],notice='';
function valid(n){return n&&typeof n.id==='string'&&typeof n.title==='string'&&typeof n.body==='string'&&typeof n.category==='string'&&typeof n.tags==='string'&&typeof n.updatedAt==='string'}
const ownerKey=()=> 'notebooks:'+(localStorage.getItem('cirurgia-sync-owner-v1')||'local');let storeName=ownerKey(),storeDB,stored,loading,queue=Promise.resolve(),saveVersion=0;
function database(){return storeDB||=new Promise((resolve,reject)=>{const r=indexedDB.open('cirurgia-notebooks-v1',1);r.onupgradeneeded=()=>r.result.createObjectStore('documents');r.onsuccess=()=>resolve(r.result);r.onerror=()=>reject(r.error);r.onblocked=()=>reject(Error('Feche as outras abas para liberar o caderno.'))})}
async function transact(mode,value,key=storeName){const db=await database();return new Promise((resolve,reject)=>{const tx=db.transaction('documents',mode),s=tx.objectStore('documents'),r=mode==='readonly'?s.get(key):s.put(value,key);let result;r.onsuccess=()=>result=r.result;tx.oncomplete=()=>resolve(result);tx.onerror=()=>reject(tx.error||r.error);tx.onabort=()=>reject(tx.error||Error('Salvamento interrompido'))})}
async function load(){if(storeName!==ownerKey()){await queue;storeName=ownerKey();loading=null;stored=null}if(loading){await loading;await queue;data=structuredClone(stored.notes);return}loading=(async()=>{let value=await transact('readonly');if(!value&&storeName!=='notebooks:local'){const unbound=await transact('readonly',undefined,'notebooks:local');if(unbound){value=unbound;await transact('readwrite',value);await transact('readwrite',{notes:[],localOnly:false},'notebooks:local')}}if(!value){const s=JSON.parse(localStorage.getItem(KEY)||'{}');value={notes:Array.isArray(s.notebooks)?s.notebooks.filter(valid):[],localOnly:false};await transact('readwrite',value)}stored=value;data=structuredClone(value.notes)})();try{await loading}catch(e){loading=null;throw e}}
function save(){const mine=++saveVersion,snapshot=structuredClone(data);notice='Salvando neste aparelho…';status();queue=queue.catch(()=>{}).then(async()=>{const study=JSON.parse(localStorage.getItem(KEY)||'{}'),next={favorites:[],done:[],known:[],pages:{},notes:{},...study,notebooks:snapshot},localOnly=new Blob([JSON.stringify(next)]).size>1500000;await transact('readwrite',{notes:snapshot,localOnly});stored={notes:snapshot,localOnly};let mirrored=false;if(!localOnly){try{localStorage.setItem(KEY,JSON.stringify(next));mirrored=true}catch{}}if(!mirrored&&!localOnly){stored.localOnly=true;await transact('readwrite',stored)}sessionStorage.removeItem(RECOVERY);if(mine===saveVersion){notice='Salvo neste aparelho · '+new Date().toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit'})+(mirrored?'':' · Caderno longo: backup/exportação disponível; sincronização deste caderno pausada');status()}if(mirrored)window.dispatchEvent(new CustomEvent('cirurgia:local',{detail:{document:'study'}}));return true}).catch(e=>{if(mine===saveVersion){notice='Não foi possível salvar: '+e.message+'. Mantenha esta aba aberta e exporte um backup.';status()}return false});return queue}

function download(name,value,type='application/json'){const u=URL.createObjectURL(new Blob([value],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),2000)}
function items(){return data.filter(n=>(filter==='trash'?!!n.deletedAt:!n.deletedAt)&&(filter!=='favorites'||n.favorite)&&(!category||n.category===category)&&(!query||fold(n.title+' '+n.body+' '+n.category+' '+n.tags).includes(fold(query)))).sort((a,b)=>(Number(b.favorite)-Number(a.favorite))||b.updatedAt.localeCompare(a.updatedAt))}
function list(){const el=root?.querySelector('#notes-list');if(!el)return;el.innerHTML=items().map(n=>`<button class="note-card ${selected===n.id?'active':''}" data-note="select" data-id="${esc(n.id)}"><small>${esc(n.category||'Sem categoria')} ${n.favorite?'★':''}</small><strong>${esc(n.title||'Sem título')}</strong><span>${esc(n.body.replace(/\s+/g,' ').slice(0,95)||'Comece a escrever…')}</span><small>${esc(n.tags)} · ${new Date(n.updatedAt).toLocaleDateString('pt-BR')}</small></button>`).join('')||'<p class="empty">Nenhuma anotação nesta seleção.</p>';root.querySelector('#notes-count').textContent=items().length+' anotações';}
function status(){const e=root?.querySelector('#note-status');if(e)e.textContent=notice;const n=data.find(n=>n.id===selected),c=root?.querySelector('#note-words');if(c)c.textContent=(n?.body.trim().split(/\s+/).filter(Boolean).length||0)+' palavras'}
function editor(){const box=root.querySelector('#notes-editor'),n=data.find(n=>n.id===selected);if(!n){box.innerHTML='<div class="notes-welcome"><h2>Um lugar para cada assunto</h2><p>Organize suas revisões, dúvidas e ideias em anotações independentes.</p><p class="hint">Use categorias como Cirurgia, Clínica, Aulas ou Ideias, e etiquetas para relacionar assuntos.</p><button class="btn primary" data-note="new">＋ Nova anotação</button></div>';return}box.innerHTML=`<div class="tools note-actions"><button class="btn" data-note="favorite">${n.favorite?'★ Favorita':'☆ Favoritar'}</button><button class="btn" data-note="text">↓ Baixar texto</button><button class="btn" data-note="${n.deletedAt?'restore':'trash'}">${n.deletedAt?'Restaurar':'Mover para lixeira'}</button></div><label>Título<input id="note-title" data-field="title" value="${esc(n.title)}" placeholder="Título do assunto" ${n.deletedAt?'disabled':''}></label><div class="note-fields"><label>Categoria<input id="note-category" data-field="category" list="note-categories" value="${esc(n.category)}" placeholder="Ex.: Cirurgia" ${n.deletedAt?'disabled':''}></label><label>Etiquetas<input id="note-tags" data-field="tags" value="${esc(n.tags)}" placeholder="Ex.: trauma, aula, revisar" ${n.deletedAt?'disabled':''}></label></div><datalist id="note-categories">${[...new Set(['Cirurgia','Clínica','Aulas','Dúvidas','Ideias',...data.map(n=>n.category)])].map(c=>`<option value="${esc(c)}">`).join('')}</datalist><label class="note-body-label">Anotação<textarea id="note-body" data-field="body" placeholder="Digite suas anotações aqui, sem limite de caracteres…" ${n.deletedAt?'disabled':''}>${esc(n.body)}</textarea></label><div class="note-save-status"><span id="note-status" role="status"></span><span id="note-words"></span></div><p class="hint">Sem limite de caracteres por anotação. Salvamento automático neste aparelho. Cadernos muito longos continuam disponíveis localmente e podem ser transferidos por Backup; a nuvem tem capacidade própria.</p>`;status()}
function render(){if(!root)return;root.innerHTML=`<div class="notes-heading"><div><h2>Caderno de estudos</h2><p class="hint">Assuntos diversos, organizados do seu jeito.</p></div><div class="tools"><button class="btn primary" data-note="new">＋ Nova anotação</button><button class="btn" data-note="export">↓ Backup</button><button class="btn" data-note="import">↑ Importar</button><input id="notes-import" type="file" accept="application/json,.json" hidden></div></div><div class="notes-layout"><aside class="notes-sidebar"><label>Buscar nas anotações<input id="notes-query" placeholder="Título, conteúdo ou etiqueta" value="${esc(query)}"></label><label>Categoria<select id="notes-category"><option value="">Todas</option>${[...new Set(data.filter(n=>!n.deletedAt).map(n=>n.category).filter(Boolean))].sort().map(c=>`<option value="${esc(c)}" ${category===c?'selected':''}>${esc(c)}</option>`).join('')}</select></label><div class="note-filter"><button class="btn ${filter==='all'?'selected':''}" data-note="filter" data-value="all">Todas</button><button class="btn ${filter==='favorites'?'selected':''}" data-note="filter" data-value="favorites">★</button><button class="btn ${filter==='trash'?'selected':''}" data-note="filter" data-value="trash">Lixeira</button></div><p id="notes-count" class="hint"></p><div id="notes-list"></div></aside><section id="notes-editor" class="notes-editor"></section></div>`;list();editor();root.onclick=click;root.oninput=async e=>{if(e.target.id==='notes-query'){query=e.target.value;list()}if(e.target.dataset.field){const n=data.find(n=>n.id===selected);if(!n||n.deletedAt)return;n[e.target.dataset.field]=e.target.value;n.updatedAt=new Date().toISOString();await save();status();list()}};root.onchange=e=>{if(e.target.id==='notes-category'){category=e.target.value;list()}if(e.target.id==='note-category'){const c=root.querySelector('#notes-category');if(e.target.value&&![...c.options].some(o=>o.value===e.target.value))c.add(new Option(e.target.value,e.target.value))}if(e.target.id==='notes-import')importNotes(e.target.files[0])}}
async function importNotes(file){if(!file)return;try{const o=JSON.parse(await file.text());if(o.format!=='cirurgia-notes-v1'||!Array.isArray(o.notes)||!o.notes.every(valid))throw Error('Este arquivo não é um backup válido do caderno.');const before=structuredClone(data),seen=new Map(data.map(n=>[n.id,n]));for(const n of o.notes){const old=seen.get(n.id);if(old&&JSON.stringify(old)===JSON.stringify(n))continue;const copy={...n};if(old){copy.id=crypto.randomUUID();copy.title+=' (importada)'}seen.set(copy.id,copy);data.push(copy)}if(!await save()){data=before;throw Error(notice)}render();alert('Anotações importadas. Versões diferentes foram mantidas separadamente.')}catch(e){alert(e.message)}}
async function click(e){const b=e.target.closest('[data-note]');if(!b)return;const n=data.find(n=>n.id===selected);switch(b.dataset.note){case'new':{const now=new Date().toISOString(),x={id:crypto.randomUUID(),title:'',body:'',category:category||'',tags:'',favorite:false,createdAt:now,updatedAt:now};data.unshift(x);selected=x.id;filter='all';query='';await save();render();root.querySelector('#note-title').focus();break}case'select':selected=b.dataset.id;list();editor();break;case'filter':filter=b.dataset.value;category='';render();break;case'favorite':if(n){n.favorite=!n.favorite;n.updatedAt=new Date().toISOString();await save();list();editor()}break;case'trash':if(n){n.deletedAt=new Date().toISOString();n.updatedAt=n.deletedAt;await save();selected=null;render()}break;case'restore':if(n){delete n.deletedAt;n.updatedAt=new Date().toISOString();await save();filter='all';render()}break;case'export':download('cirurgia-anotacoes-backup.json',JSON.stringify({format:'cirurgia-notes-v1',exportedAt:new Date().toISOString(),notes:data},null,2));break;case'text':if(n)download((n.title||'anotacao').replace(/[^\p{L}\p{N} -]/gu,'').slice(0,80)+'.txt',n.title+'\n'+n.category+'\n'+n.tags+'\n\n'+n.body,'text/plain;charset=utf-8');break;case'import':root.querySelector('#notes-import').click();break}}
window.CirurgiaNotes={async mount(el){root=el;el.innerHTML='<p>Carregando seu caderno…</p>';try{await load()}catch(e){el.innerHTML='<p>Não foi possível abrir o armazenamento do caderno. Reabra o navegador antes de editar.</p>';return}if(root!==el)return;try{const r=JSON.parse(sessionStorage.getItem(RECOVERY)||'null');if(Array.isArray(r)&&r.every(valid)){data=r;notice='Rascunho recuperado. Exporte um backup para guardá-lo.'}}catch{}render()},unmount(){root=null}};
window.addEventListener('cirurgia:remote',async e=>{if(e.detail?.document!=='study')return;try{if(!loading||storeName!==ownerKey())await load();else await loading;await queue;if(stored.localOnly){notice='Caderno longo preservado neste aparelho. Use Backup para transferi-lo.';status();return}const remote=JSON.parse(localStorage.getItem(KEY)||'{}').notebooks;if(!Array.isArray(remote)||!remote.every(valid)){if(root)render();return;}const incoming=structuredClone(remote);await transact('readwrite',{notes:incoming,localOnly:false});stored={notes:incoming,localOnly:false};data=incoming;if(root){notice='Anotações recebidas da sincronização';render()}}catch(e){notice='Falha ao receber anotações: '+e.message;status()}});
})();
